-- We first theme base16, but we also need to fix some other colors that don't
-- contrast well by default

-- Helper function to set multiple highlight groups at once
local function set_hl_mutliple(groups, value)
  for _, v in pairs(groups) do
    vim.api.nvim_set_hl(0, v, value)
  end
end

-- Make selected text stand out more
vim.api.nvim_set_hl(0, 'Visual', {
  bg = '#434078',
  fg = '#e3dfff',
})

local normal_bg = '#0e0e13'

vim.api.nvim_set_hl(0, 'Normal', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'NormalFloat', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'FloatBorder', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'LspHover', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'NormalNC', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'StatusLine', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'StatusLineNC', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'LineNr', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'LineNrAbove', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'LineNrBelow', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'SignColumn', { bg = normal_bg })

vim.api.nvim_set_hl(0, 'Pmenu', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'PmenuSel', { bg = "#2b3132" }) -- Keep selection visible
vim.api.nvim_set_hl(0, 'PmenuSbar', { bg = normal_bg })
vim.api.nvim_set_hl(0, 'PmenuThumb', { bg = normal_bg })

-- Make "string" text contrast better
set_hl_mutliple({ 'String', 'TSString' }, {
  fg = '#d87eaa',
})

-- Grey out comments
set_hl_mutliple({ 'TSComment', 'Comment' }, {
  fg = '#928f9a',
  italic = true,
})

-- Color in other highlight groups as you see fit!

set_hl_mutliple({ 'TSMethod', 'Method' }, {
  fg = '#eab9d1',
})


set_hl_mutliple({ 'TSFunction', 'Function' }, {
  fg = '#c7c4dd',
})

set_hl_mutliple({ 'Keyword', 'TSKeyword', 'TSKeywordFunction', 'TSRepeat' }, {
  fg = '#5a5891',
})
